const { chromium } = require(process.env.PW);
(async () => {
  const b = await chromium.launch({ channel: 'chrome' });
  for (const dir of process.argv.slice(2)) {
    const p = await b.newPage(); const errs = [];
    p.on('pageerror', e => errs.push(e.message));
    await p.goto('file://' + dir + '/index.html'); await p.waitForTimeout(300);
    const lis = await p.$$eval('li', els => els.map(e => e.textContent));
    console.log(dir.split('/').pop(), JSON.stringify({ lis, errs }));
  }
  await b.close();
})();
EOF
PW=$(dirname $(npx --no-install playwright --help >/dev/null 2>&1; find ~/.npm/_npx -path '*node_modules/playwright/package.json' 2>/dev/null | head -1)) node $S/probe.js "$PWD" $S/base; echo exit=$?

